 1→/**
 2→ * electron-builder afterPack hook
 3→ *
 4→ * Copies the pre-compiled macOS 26+ Liquid Glass icon (Assets.car) into the
 5→ * app bundle. The Assets.car file is compiled locally using actool with the
 6→ * macOS 26 SDK (not available in CI), then committed to the repo.
 7→ *
 8→ * To regenerate Assets.car after icon changes:
 9→ *   cd apps/electron
10→ *   xcrun actool "resources/icon.icon" --compile "resources" \
11→ *     --app-icon AppIcon --minimum-deployment-target 26.0 \
12→ *     --platform macosx --output-partial-info-plist /dev/null
13→ *
14→ * For older macOS versions, the app falls back to icon.icns which is
15→ * included separately by electron-builder.
16→ */
17→
18→const path = require('path');
19→const fs = require('fs');
20→
21→module.exports = async function afterPack(context) {
22→  // Only process macOS builds
23→  if (context.electronPlatformName !== 'darwin') {
24→    console.log('Skipping Liquid Glass icon (not macOS)');
25→    return;
26→  }
27→
28→  const appPath = context.appOutDir;
29→  const resourcesDir = path.join(appPath, 'Orcha Agents.app', 'Contents', 'Resources');
30→  const precompiledAssets = path.join(context.packager.projectDir, 'resources', 'Assets.car');
31→
32→  console.log(`afterPack: projectDir=${context.packager.projectDir}`);
33→  console.log(`afterPack: looking for Assets.car at ${precompiledAssets}`);
34→
35→  // Check if pre-compiled Assets.car exists
36→  if (!fs.existsSync(precompiledAssets)) {
37→    console.log('Warning: Pre-compiled Assets.car not found in resources/');
38→    console.log('The app will use the fallback icon.icns on all macOS versions');
39→    return;
40→  }
41→
42→  // Copy pre-compiled Assets.car to the app bundle
43→  const destAssetsCar = path.join(resourcesDir, 'Assets.car');
44→  try {
45→    fs.copyFileSync(precompiledAssets, destAssetsCar);
46→    console.log(`Liquid Glass icon copied: ${destAssetsCar}`);
47→  } catch (err) {
48→    // Don't fail the build if Assets.car can't be copied - app will use fallback icon.icns
49→    console.log(`Warning: Could not copy Assets.car: ${err.message}`);
50→    console.log('The app will use the fallback icon.icns on all macOS versions');
51→  }
52→};
