152→export function updateBadgeCount(count: number): void {
153→  // Skip if count hasn't changed
154→  if (count === currentBadgeCount) {
155→    return
156→  }
157→
158→  currentBadgeCount = count
159→
160→  if (process.platform === 'darwin') {
161→    updateBadgeCountMacOS(count)
162→  } else if (process.platform === 'win32') {
163→    updateBadgeCountWindows(count)
164→  } else if (process.platform === 'linux') {
165→    updateBadgeCountLinux(count)
166→  }
167→}
