169→/**
170→ * Update badge count on macOS using dock icon overlay
171→ */
172→function updateBadgeCountMacOS(count: number): void {
173→  try {
174→    if (count > 0) {
175→      // Draw badge onto icon using the renderer process (Canvas API)
176→      if (eventSink && baseIconDataUrl) {
177→        eventSink(RPC_CHANNELS.badge.DRAW, { to: 'all' }, { count, iconDataUrl: baseIconDataUrl })
178→      }
179→    } else {
180→      // Reset to original icon (no badge)
181→      if (baseIconPath) {
182→        const originalIcon = nativeImage.createFromPath(baseIconPath)
183→        app.dock?.setIcon(originalIcon)
184→      }
185→    }
186→    mainLog.info('Badge count updated (macOS):', count)
187→  } catch (error) {
188→    mainLog.error('Failed to update badge count (macOS):', error)
189→  }
190→}
191→
192→/**
193→ * Update badge count on Windows using taskbar overlay icon
194→ */
195→function updateBadgeCountWindows(count: number): void {
196→  try {
197→    if (count > 0) {
198→      // Draw overlay icon using the renderer process (Canvas API)
199→      if (eventSink) {
200→        eventSink(RPC_CHANNELS.badge.DRAW_WINDOWS, { to: 'all' }, { count })
201→      }
202→    } else {
203→      // Clear the overlay on all windows
204→      const windows = BrowserWindow.getAllWindows()
205→      for (const window of windows) {
206→        if (!window.isDestroyed()) {
207→          window.setOverlayIcon(null, '')
208→        }
209→      }
210→    }
211→    mainLog.info('Badge count updated (Windows):', count)
212→  } catch (error) {
213→    mainLog.error('Failed to update badge count (Windows):', error)
214→  }
215→}
