220→function updateBadgeCountLinux(count: number): void {
221→  try {
222→    // Electron's setBadgeCount works on Linux with Unity launcher and KDE
223→    app.setBadgeCount(count)
224→    mainLog.info('Badge count updated (Linux):', count)
