224→// Accept self-signed / untrusted certificates when connecting to a user-configured remote server.
225→// Only bypasses cert validation for the exact CRAFT_SERVER_URL origin — all other connections
226→// use standard certificate verification. Without this, wss:// to self-signed servers fails with
227→// ERR_CERT_AUTHORITY_INVALID because Chromium's WebSocket rejects untrusted certs.
228→//
229→// Electron's certificate-error always reports URLs with https:// scheme, so we normalize
230→// wss:// → https:// (and ws:// → http://) to ensure origins compare correctly.
231→function normalizeOriginForCert(urlStr: string): string {
232→  const u = new URL(urlStr)
233→  if (u.protocol === 'wss:') u.protocol = 'https:'
234→  else if (u.protocol === 'ws:') u.protocol = 'http:'
235→  return u.origin
236→}
237→
238→if (process.env.CRAFT_SERVER_URL) {
239→  let serverOrigin: string | undefined
240→  try {
241→    serverOrigin = normalizeOriginForCert(process.env.CRAFT_SERVER_URL)
242→  } catch {
243→    // Invalid URL — will fail later during connection, no need to handle here
244→  }
245→  if (serverOrigin) {
246→    app.on('certificate-error', (event, _webContents, url, _error, _certificate, callback) => {
247→      try {
248→        if (normalizeOriginForCert(url) === serverOrigin) {
249→          event.preventDefault()
250→          callback(true)
251→          return
252→        }
253→      } catch {
254→        // URL parse failure — fall through to default rejection
255→      }
256→      callback(false)
257→    })
258→  }
259→}
