 43→/**
 44→ * Find a file in directory matching the pattern case-insensitively.
 45→ * Returns the actual filename if found, null otherwise.
 46→ */
 47→function findFileCaseInsensitive(directory: string, pattern: string): string | null {
 48→  try {
 49→    const files = readdirSync(directory);
 50→    const lowerPattern = pattern.toLowerCase();
 51→    return files.find((f) => f.toLowerCase() === lowerPattern) ?? null;
 52→  } catch {
