 63→  for (const pattern of CONTEXT_FILE_PATTERNS) {
 64→    const actualFilename = findFileCaseInsensitive(directory, pattern);
 65→    if (actualFilename) {
 66→      debug(`[findProjectContextFile] Found ${actualFilename}`);
