 13→import type { PresetTheme } from '@config/theme'
 14→import { ThemeToggle } from './ThemeToggle'
 15→import { Sidebar } from './Sidebar'
 16→import { ComponentPreview } from './ComponentPreview'
 17→import { VariantsSidebar } from './VariantsSidebar'
 18→import { getCategories, getComponentById, type ComponentVariant } from './registry'
 19→
 20→const SELECTED_STORAGE_KEY = 'playground-selected-component'
 21→const VARIANTS_SIDEBAR_KEY = 'playground-variants-sidebar-open'
 22→
 23→const FALLBACK_THEME_OPTIONS = [
 24→  { value: 'default', label: 'Default' },
 25→  { value: 'catppuccin', label: 'Catppuccin' },
 26→  { value: 'dracula', label: 'Dracula' },
 27→  { value: 'ghostty', label: 'Ghostty' },
 28→  { value: 'github', label: 'GitHub' },
 29→  { value: 'gruvbox', label: 'Gruvbox' },
