 34→  { value: 'pierre', label: 'Pierre' },
 35→  { value: 'rose-pine', label: 'Rosé Pine' },
 36→  { value: 'solarized', label: 'Solarized' },
 37→  { value: 'tokyo-night', label: 'Tokyo Night' },
 38→  { value: 'vitesse', label: 'Vitesse' },
 39→] as const
