 41→export function PlaygroundApp() {
 42→  const categories = React.useMemo(() => getCategories(), [])
 43→  const {
 44→    workspaceColorTheme,
 45→    effectiveColorTheme,
 46→    setColorTheme,
 47→    setWorkspaceColorTheme,
 48→    setPreviewColorTheme,
 49→    activeWorkspaceId,
 50→  } = useTheme()
 51→  const [presetThemes, setPresetThemes] = React.useState<PresetTheme[]>([])
 52→  const [selectedId, setSelectedId] = React.useState<string | null>(() => {
 53→    // Try to restore from localStorage
 54→    try {
 55→      const stored = localStorage.getItem(SELECTED_STORAGE_KEY)
 56→      if (stored) {
 57→        // Verify the component still exists
 58→        const component = getComponentById(stored)
 59→        if (component) {
 60→          return stored
 61→        }
 62→      }
 63→    } catch {
 64→      // Ignore parse errors
 65→    }
 66→    return null
 67→  })
 68→  const [props, setProps] = React.useState<Record<string, unknown>>({})
 69→  const [selectedVariant, setSelectedVariant] = React.useState<string | null>(null)
 70→  const [variantsSidebarOpen, setVariantsSidebarOpen] = React.useState(() => {
 71→    try {
 72→      const stored = localStorage.getItem(VARIANTS_SIDEBAR_KEY)
 73→      return stored !== 'false' // Default to open
 74→    } catch {
 75→      return true
 76→    }
 77→  })
 78→
 79→  React.useEffect(() => {
 80→    const loadThemes = async () => {
 81→      if (!window.electronAPI?.loadPresetThemes) {
 82→        console.warn('[Playground] electronAPI.loadPresetThemes is unavailable; using fallback theme options')
 83→        setPresetThemes([])
 84→        return
 85→      }
 86→
 87→      try {
 88→        const themes = await window.electronAPI.loadPresetThemes()
 89→        setPresetThemes(themes)
 90→      } catch (error) {
 91→        console.error('[Playground] Failed to load preset themes, using fallback options:', error)
 92→        setPresetThemes([])
 93→      }
 94→    }
 95→
 96→    void loadThemes()
 97→  }, [])
 98→
 99→  const themeOptions = React.useMemo(() => {
100→    const loadedOptions = presetThemes.map(theme => ({
101→      value: theme.id,
102→      label: theme.theme.name || theme.id,
103→    }))
104→
105→    const merged = new Map<string, string>()
106→
107→    for (const option of FALLBACK_THEME_OPTIONS) {
108→      merged.set(option.value, option.label)
109→    }
110→
111→    for (const option of loadedOptions) {
112→      merged.set(option.value, option.label)
113→    }
114→
115→    return Array.from(merged.entries()).map(([value, label]) => ({ value, label }))
116→  }, [presetThemes])
117→
118→  React.useEffect(() => {
119→    return () => {
120→      setPreviewColorTheme(null)
121→    }
122→  }, [setPreviewColorTheme])
123→
124→  // Persist selected component to localStorage
125→  React.useEffect(() => {
126→    try {
127→      if (selectedId) {
128→        localStorage.setItem(SELECTED_STORAGE_KEY, selectedId)
129→      } else {
130→        localStorage.removeItem(SELECTED_STORAGE_KEY)
131→      }
132→    } catch {
133→      // Ignore storage errors
134→    }
135→  }, [selectedId])
136→
137→  // Persist variants sidebar state
138→  React.useEffect(() => {
139→    try {
140→      localStorage.setItem(VARIANTS_SIDEBAR_KEY, String(variantsSidebarOpen))
141→    } catch {
142→      // Ignore storage errors
143→    }
144→  }, [variantsSidebarOpen])
145→
146→  const selectedComponent = selectedId ? (getComponentById(selectedId) ?? null) : null
147→
148→  // Reset props when component changes
149→  React.useEffect(() => {
150→    if (selectedComponent) {
151→      const defaults: Record<string, unknown> = {}
152→      for (const prop of selectedComponent.props) {
153→        defaults[prop.name] = prop.defaultValue
154→      }
155→      setProps(defaults)
156→      setSelectedVariant(null)
157→    }
158→  }, [selectedComponent])
159→
160→  const handleVariantSelect = (variant: ComponentVariant) => {
161→    if (selectedComponent) {
162→      // Start with defaults, then apply variant props
163→      const defaults: Record<string, unknown> = {}
164→      for (const prop of selectedComponent.props) {
165→        defaults[prop.name] = prop.defaultValue
166→      }
167→      setProps({ ...defaults, ...variant.props })
168→      setSelectedVariant(variant.name)
169→    }
170→  }
171→
172→  const handlePropsChange = (newProps: Record<string, unknown>) => {
173→    setProps(newProps)
174→    // Clear variant selection when props are manually changed
175→    setSelectedVariant(null)
176→  }
177→
178→  const handleThemeChange = (nextTheme: string) => {
179→    const normalized = nextTheme === 'default' ? null : nextTheme
180→
181→    // Apply immediately regardless of persistence layer
182→    setPreviewColorTheme(normalized)
183→
184→    // Respect current precedence: if a workspace override is active, update that;
185→    // otherwise update app default theme.
186→    if (workspaceColorTheme !== null && activeWorkspaceId) {
187→      setWorkspaceColorTheme(normalized)
188→      return
189→    }
190→
191→    setColorTheme(nextTheme)
192→  }
193→
194→  return (
195→    <div className="h-screen flex flex-col bg-background text-foreground">
196→      {/* Header */}
197→      <header className="h-12 shrink-0 flex items-center justify-between px-4 border-b border-border bg-background">
198→        <div className="flex items-center gap-3">
199→          <CraftAgentsSymbol className="h-5 w-5" />
200→          <h1 className="font-semibold text-foreground font-sans">
201→            Design System Playground
202→          </h1>
203→        </div>
204→        <div className="flex items-center gap-2">
205→          <ThemeToggle />
206→          <Select value={effectiveColorTheme ?? 'default'} onValueChange={handleThemeChange}>
207→            <SelectTrigger className="h-8 w-[170px] bg-foreground/5 border-border/50 text-xs">
208→              <SelectValue placeholder="Theme" />
209→            </SelectTrigger>
210→            <SelectContent>
211→              {themeOptions.map((option) => (
212→                <SelectItem key={option.value} value={option.value}>
213→                  {option.label}
214→                </SelectItem>
215→              ))}
216→            </SelectContent>
217→          </Select>
218→          <button
219→            onClick={() => setVariantsSidebarOpen(!variantsSidebarOpen)}
220→            className={cn(
221→              'p-2 rounded-md transition-colors',
222→              variantsSidebarOpen
223→                ? 'bg-foreground/10 text-foreground'
224→                : 'text-muted-foreground hover:text-foreground hover:bg-foreground/5'
225→            )}
226→            title={variantsSidebarOpen ? 'Hide variants' : 'Show variants'}
227→          >
228→            <PanelRight className="w-4 h-4" />
229→          </button>
230→        </div>
231→      </header>
232→
233→      {/* Main content */}
234→      <div className="flex-1 flex overflow-hidden">
235→        {/* Left Sidebar - Component list */}
236→        <Sidebar
237→          categories={categories}
238→          selectedId={selectedId}
239→          onSelect={setSelectedId}
240→        />
241→
242→        {/* Content area - full height preview */}
243→        {selectedComponent ? (
244→          <ComponentPreview
245→            component={selectedComponent}
246→            props={props}
247→          />
248→        ) : (
249→          <div className="flex-1 flex items-center justify-center text-muted-foreground">
250→            Select a component from the sidebar
251→          </div>
252→        )}
253→
254→        {/* Right Sidebar - Variants & Props */}
255→        <VariantsSidebar
256→          component={selectedComponent}
257→          selectedVariant={selectedVariant}
258→          onVariantSelect={handleVariantSelect}
259→          props={props}
260→          onPropsChange={handlePropsChange}
261→          isOpen={variantsSidebarOpen}
262→        />
263→      </div>
264→    </div>
265→  )
266→}
